bool colored(ID3D11Texture2D* texture){
    if(!texture)return false;Com<ID3D11Device> device;texture->GetDevice(device.put());Com<ID3D11DeviceContext> context;device->GetImmediateContext(context.put());D3D11_TEXTURE2D_DESC desc;texture->GetDesc(&desc);desc.BindFlags=0;desc.MiscFlags=0;desc.Usage=D3D11_USAGE_STAGING;desc.CPUAccessFlags=D3D11_CPU_ACCESS_READ;Com<ID3D11Texture2D> readback;if(FAILED(device->CreateTexture2D(&desc,nullptr,readback.put())))return false;context->CopyResource(readback.p,texture);D3D11_MAPPED_SUBRESOURCE mapped;if(FAILED(context->Map(readback.p,0,D3D11_MAP_READ,0,&mapped)))return false;auto top=(BYTE*)mapped.pData+10*mapped.RowPitch+10*4;auto bottom=(BYTE*)mapped.pData+(desc.Height-10)*mapped.RowPitch+10*4;auto marker=(BYTE*)mapped.pData+50*mapped.RowPitch+50*4;static bool logged=false;if(!logged){logged=true;std::cout<<"Pixel BGR top="<<(int)top[0]<<","<<(int)top[1]<<","<<(int)top[2]<<" bottom="<<(int)bottom[0]<<","<<(int)bottom[1]<<","<<(int)bottom[2]<<" marker="<<(int)marker[0]<<","<<(int)marker[1]<<","<<(int)marker[2]<<"\n";}bool ok=top[1]>180&&top[0]<80&&bottom[0]>180&&bottom[1]<80&&marker[0]>180&&marker[2]>180&&marker[1]<80;context->Unmap(readback.p,0);return ok;
}
